@startuml

class Employee {
  + name : string
  + socialSecurityNumber : string
}

class Planner extends Employee {
  + username : string
  + password : string
}

class AdministrativeStaff extends Employee {
  + username : string
  + password : string
  + fieldOfActivity : string
}

class Customer {
  + name : string
  + billingAddress : string
}

class PartnerCompany {
  + name : string
  + address : string
}

class Vehicle {
  + licensePlate : string
  + mileage : int
}

class RefrigeratedTruck extends Vehicle {}

class SmallVan extends Vehicle {}

class LoadingPlatform extends Vehicle {}

class BoxTruck extends Vehicle {}

class RepairShop {
  + name : string
  + address : string
}

class Repair {
  + duration : string
  + cost : float
}

class Order {
  + packageSize : string
  + comment : string
  + startTime : datetime
  + finishTime : datetime
  + pickUpAddress : string
  + deliveryAddress : string
}

class Assignment {
}

Employee "1" -- "*" Repair : takes vehicle to
Repair "*" -- "1" Vehicle
Repair "*" -- "1" RepairShop

Order "*" -- "1" Customer : placed by
Order "*" -- "0..1" PartnerCompany : placed by
Order "*" -- "1" Vehicle : assigned to
Order "*" -- "1" Planner : assigned by
Order "*" -- "1" Driver : completed by
Order "*" -- "1" Assignment : involves
Assignment "*" -- "1" Driver : executes
Assignment "*" -- "1" Vehicle : uses

@enduml

